(() => {
  'use strict';
  const editorSelector = '[data-composer-markdown]';
  const sendSelector = 'button[type="submit"][aria-label="送信"]';
  const composing = new WeakSet();
  // Only descendants synchronously generated by this gesture may reuse its decision.
  const decisions = new WeakMap();
  function decide(form, event, origin) {
    const prior = decisions.get(form);
    if (prior && (event.type === 'submit' ||
        (prior.origin === 'keydown' && event.type === 'click' && event.detail === 0))) {
      if (!prior.allowed) block(event);
      return;
    }
    let allowed = false;
    try { allowed = window.confirm('Workモードで送信しますか？\nこのメッセージはWorkモードで実行されます。'); }
    catch { /* A failed dialog never authorizes submission. */ }
    const decision = { allowed, origin };
    decisions.set(form, decision);
    setTimeout(() => {
      if (decisions.get(form) === decision) decisions.delete(form);
    }, 0);
    if (!allowed) block(event);
  }
  function block(event) {
    event.preventDefault();
    event.stopImmediatePropagation();
  }
  function isWork(form) {
    return !!form.querySelector('[data-composer-input-variant="work-home"], [data-composer-markdown][aria-label="Work モードで作成"]');
  }
  document.addEventListener('compositionstart', event => {
    const editor = event.target.closest?.(editorSelector);
    if (editor) composing.add(editor);
  }, true);
  document.addEventListener('compositionend', event => {
    const editor = event.target.closest?.(editorSelector);
    if (editor) composing.delete(editor);
  }, true);
  function handle(event) {
    const target = event.target;
    if (!(target instanceof Element)) return;
    let form;
    if (event.type === 'click') {
      const button = target.closest(sendSelector);
      if (!button || button.disabled) return;
      form = button.form;
    } else if (event.type === 'keydown') {
      const editor = target.closest(editorSelector);
      if (!editor || event.key !== 'Enter' || event.shiftKey || event.ctrlKey ||
          event.altKey || event.metaKey || event.isComposing || event.keyCode === 229 ||
          composing.has(editor)) return;
      form = editor.closest('form');
      if (form && isWork(form) && event.repeat) { block(event); return; }
    } else {
      form = target.closest('form');
    }
    if (!form || !isWork(form)) return;
    decide(form, event, event.type);
  }
  for (const type of ['click', 'keydown', 'submit']) {
    document.addEventListener(type, handle, true);
  }
})();
